head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// $p.data.create 로 생성 후 $p.getComponentById -> getObjectType() 을 출력
scwin.createAndPrint = function (strId, objInfo) {
    if ($p.getComponentById(strId)) {
        $p.data.remove(strId);
    }
    $p.data.create(objInfo);

    var objCol = $p.getComponentById(strId);
    scwin.setReturnValue("[" + objInfo.type + "] id : " + strId
        + "  객체 : " + (objCol ? "객체 반환" : "null")
        + "  getObjectType() : " + (objCol ? objCol.getObjectType() : "null"));
};

scwin.btn_create_onclick = function (e) {
    // 비교 대상 1 : aliasDataList (양쪽 동일 동작)
    scwin.createAndPrint("adl_exam", {
        "id" : "adl_exam",
        "type" : "aliasDataList",
        "option" : { "scope" : "parent", "bind" : "dlt_base", "baseNode" : "list", "repeatNode" : "map" }
    });

    // 검증 대상 : aliasDataMap
    scwin.createAndPrint("adm_exam", {
        "id" : "adm_exam",
        "type" : "aliasDataMap",
        "option" : { "scope" : "parent", "bind" : "dma_base", "baseNode" : "map" }
    });
};
